finished","target_category":"boulangerie","component_name":"Levure Jaouda","component_order":5},{"target_name":"PATE SPECIAL","target_type":"semi_finished","target_category":"boulangerie","component_name":"Farine boulangerie","component_order":1},{"target_name":"PATE SPECIAL","target_type":"semi_finished","target_category":"boulangerie","component_name":"Farine traditionel","component_order":2},{"target_name":"PATE SPECIAL","target_type":"semi_finished","target_category":"boulangerie","component_name":"Levure Traditionnelle","component_order":3},{"target_name":"PATE SPECIAL","target_type":"semi_finished","target_category":"boulangerie","component_name":"Grand Chef","component_order":4},{"target_name":"PATE SPECIAL","target_type":"semi_finished","target_category":"boulangerie","component_name":"Levure Jaouda","component_order":5},{"target_name":"PATE SPECIAL","target_type":"semi_finished","target_category":"boulangerie","component_name":"Seigle","component_order":6},{"target_name":"PATE SPECIAL","target_type":"semi_finished","target_category":"boulangerie","component_name":"Sel","component_order":7},{"target_name":"PATE SPECIAL","target_type":"semi_finished","target_category":"boulangerie","component_name":"Eau","component_order":8}]$links$::jsonb) as input(
    target_name text, target_type text, target_category text, component_name text, component_order integer
  )
),
active_recipes as (
  select p.name, p.type::text as product_type, p.category, r.id as recipe_id
  from expected_products ep
  join products p on p.type = ep.product_type::product_type
    and p.category = ep.category
    and lower(trim(p.name)) = lower(trim(ep.name))
    and p.is_active = true
  join recipes r on r.product_id = p.id and r.is_active = true
),
actual_links as (
  select target.name as target_name, component.name as component_name
  from active_recipes ar
  join products target on lower(trim(target.name)) = lower(trim(ar.name))
    and target.type = ar.product_type::product_type
    and target.category = ar.category
  join recipe_components rc on rc.recipe_id = ar.recipe_id
  join products component on component.id = rc.component_product_id
),
missing_products as (
  select ep.name
  from expected_products ep
  where not exists (
    select 1 from products p
    where p.type = ep.product_type::product_type
      and p.category = ep.category
      and p.is_active = true
      and lower(trim(p.name)) = lower(trim(ep.name))
  )
),
missing_codes as (
  select ep.name
  from expected_products ep
  join products p on p.type = ep.product_type::product_type
    and p.category = ep.category
    and lower(trim(p.name)) = lower(trim(ep.name))
  where nullif(trim(coalesce(p.lot_zone, '')), '') is null
    or nullif(trim(coalesce(p.lot_code, '')), '') is null
),
missing_links as (
  select el.target_name || ' -> ' || el.component_name as link_name
  from expected_links el
  where not exists (
    select 1 from actual_links al
    where lower(trim(al.target_name)) = lower(trim(el.target_name))
      and lower(trim(al.component_name)) = lower(trim(el.component_name))
  )
)
select
  (select count(*) from expected_products) as expected_products,
  (select count(*) from expected_links) as expected_component_links,
  (select count(*) from active_recipes) as active_schema_count,
  (select count(*) from actual_links) as active_component_link_count,
  coalesce((select jsonb_agg(name order by name) from missing_products), '[]'::jsonb) as missing_products,
  coalesce((select jsonb_agg(name order by name) from missing_codes), '[]'::jsonb) as missing_lot_codifications,
  coalesce((select jsonb_agg(link_name order by link_name) from missing_links), '[]'::jsonb) as missing_component_links;
